 function saveImage(){
  const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),width=1600,padding=100,maxWidth=width-padding*2,lineHeight=48;
  ctx.font='30px system-ui, sans-serif';
  const lines=[];
  guideText().split('\n').forEach(raw=>{if(!raw){lines.push('');return;}let line='';for(const char of raw){if(ctx.measureText(line+char).width>maxWidth&&line){lines.push(line);line=char;}else line+=char;}lines.push(line);});
  canvas.width=width;canvas.height=Math.max(1200,260+lines.length*lineHeight+padding);ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#eff6fe';ctx.fillRect(0,0,width,170);ctx.fillStyle='#071843';ctx.font='600 48px system-ui, sans-serif';ctx.fillText('寫前藍圖',padding,105);ctx.font='30px system-ui, sans-serif';let y=230;for(const line of lines){ctx.fillStyle=line.endsWith('：')||line==='寫前指導'?'#175cff':'#071843';ctx.fillText(line,padding,y);y+=lineHeight;}
  canvas.toBlob(blob=>{if(!blob){message='未能保存图片，请稍后重试。';render();return;}const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='寫前藍圖.png';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message='图片已保存。';render();},'image/png');
 }
