  const recognition=new Recognition();voiceSession=recognition;recognition.lang='zh-HK';recognition.continuous=false;recognition.interimResults=false;
  recognition.onstart=()=>{button.innerHTML=stopVoiceIcon;button.setAttribute('aria-label','停止語音輸入');button.title='停止語音輸入';button.setAttribute('aria-pressed','true');hint.textContent='正在聆聽…';};
