  recognition.onerror=event=>{if(hint.isConnected)hint.textContent=event.error==='not-allowed'?'未取得麥克風權限，可直接輸入文字。':'未能辨識，請重試或直接輸入。';};
  recognition.onend=()=>{if(voiceSession===recognition)voiceSession=null;if(button.isConnected){button.innerHTML=microphoneIcon;button.setAttribute('aria-label',button.dataset.voiceLabel);button.title='語音輸入';button.setAttribute('aria-pressed','false');if(hint.textContent==='正在聆聽…')hint.textContent='未收到內容，可以再試一次。';}};
